if(serverMode){
const role=sessionUser.role;
document.querySelector('.save-status').innerHTML='<i></i> Mit Server verbunden';
document.querySelector('.profile strong').textContent=sessionUser.name;
document.querySelector('.profile small').textContent=role==='admin'?'Administrator':'Benutzer';
const adminNav=document.querySelector('[data-view="admin"]');
if(role!=='admin')adminNav.hidden=true;
if(role==='admin'){const btn=document.createElement('button');btn.className='nav';btn.dataset.view='access';btn.innerHTML='<span>♙</span> Benutzer & Gruppen';btn.onclick=()=>navigate('access');adminNav.before(btn)}
const signout=document.createElement('a');signout.href='/signout-with-chatgpt?return_to=%2F';signout.target='_top';signout.className='signout';signout.textContent='Abmelden ↗';document.querySelector('.header-actions').prepend(signout);
document.querySelector('#info p:last-of-type').textContent='Die Anmeldung erfolgt über ChatGPT. Benutzer sehen nur Lernbereiche, die ihrer Gruppe zugeordnet sind. Lernfortschritt und Inhalte werden auf dem Server gespeichert. Admins verwalten Inhalte, Benutzer und Freigaben.';
}
let serverVersion=window.__LUMIO_SERVER__?.version,saveQueue=Promise.resolve();
const coursePayload=()=>({topics:state.topics.map(t=>({id:t.id,course:t.course})),companion:state.companion});
let lastServerContent=serverMode?JSON.stringify(coursePayload()):'';
async function api(path,method='GET',data){const response=await fetch(path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});const result=await response.json();if(!response.ok){if(response.status===401||response.status===403){document.body.innerHTML='';location.reload()}throw Error(result.error||'Die Anfrage ist fehlgeschlagen.')}return result}
function applyServerData(data){const selectedId=state.topics[state.activeTopic]?.id,selectedIndex=state.activeTopic;state=normalizeState(data);const next=state.topics.findIndex(t=>t.id===selectedId);state.activeTopic=next>=0?next:Math.min(selectedIndex,Math.max(0,state.topics.length-1));serverVersion=data.version;lastServerContent=JSON.stringify(coursePayload());storageOK=true}
function scheduleServerSave(){const snapshot=coursePayload(),content=JSON.stringify(snapshot),topic=state.topics[state.activeTopic],current=topic?.current;document.body.dataset.saving='true';const operation=saveQueue.then(async()=>{try{if(sessionUser.role==='admin'&&content!==lastServerContent){const data=await api('/api/state','PUT',{...snapshot,version:serverVersion});applyServerData(data);if(view!=='access')render();toast('Änderungen auf dem Server gespeichert.')}else if(topic?.id){await api('/api/progress','PUT',{topicId:topic.id,current});storageOK=true}document.querySelector('.save-status').innerHTML='<i></i> Auf Server gespeichert'}catch(error){storageOK=false;document.querySelector('.save-status').textContent='Nicht gespeichert';toast(error.message)}finally{document.body.dataset.saving='false'}});saveQueue=operation;return operation}
async function submitServerQuiz(answer){if(document.body.dataset.saving==='true')return;document.body.dataset.saving='true';const topic=state.topics[state.activeTopic],chapter=state.current;try{await saveQueue;const result=await api('/api/quiz','POST',{topicId:topic.id,chapter,answer});const y=window.scrollY;applyServerData(result);render();window.scrollTo(0,y)}catch(error){toast(error.message)}finally{document.body.dataset.saving='false'}}
async function renderAccess(){document.querySelector('#breadcrumb').textContent='Benutzer & Gruppen';document.querySelector('#content').innerHTML=heading('ADMINISTRATION','Benutzer, Gruppen und Freigaben.','Benutzer melden sich mit dem hier hinterlegten ChatGPT-Konto an.');document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view==='access'));try{await saveQueue;const access=await api('/api/access');if(view!=='access')return;const root=document.querySelector('#content');root.innerHTML+=`<div class="access-grid"><section class="admin-card glass"><h3>Gruppe anlegen</h3><form id="group-form"><label for="group-name">Name der Gruppe</label><input id="group-name" name="name" required maxlength="100" placeholder="z. B. Klasse 3a"><button class="primary">Gruppe anlegen</button></form><h3 style="margin-top:28px">Lernbereiche freigeben</h3><form id="assign-form"><label for="access-group">Gruppe</label><select id="access-group" name="groupId" required><option value="">Gruppe wählen</option>${access.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select><div id="assignment-topics"><p>Wähle eine Gruppe.</p></div><button class="primary" ${access.groups.length?'':'disabled'}>Freigaben speichern</button></form></section><section class="admin-card glass"><h3>Benutzer anlegen oder bearbeiten</h3><form id="member-form"><label for="member-name">Name</label><input id="member-name" name="name" required maxlength="100"><label for="member-email">E-Mail des ChatGPT-Kontos</label><input id="member-email" name="email" type="email" required><label for="member-role">Rolle</label><select id="member-role" name="role"><option value="user">Benutzer</option><option value="admin">Admin · vollständiger Zugriff</option></select><label for="member-group">Gruppe</label><select id="member-group" name="groupId"><option value="">Keine Gruppe</option>${access.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select><label class="choice"><input type="checkbox" name="active" checked> Zugang aktiv</label><button class="primary">Benutzer speichern</button><p>Ohne Gruppe oder Freigaben sehen Benutzer keine Lerninhalte. Das Eigentümerkonto ist geschützt.</p></form></section><section class="admin-card glass access-members"><h3>Benutzerübersicht</h3><div class="table-wrap"><table><thead><tr><th>Name / E-Mail</th><th>Rolle</th><th>Gruppe</th><th>Status</th><th></th></tr></thead><tbody>${access.members.map((m,i)=>`<tr><td><strong>${esc(m.name)}</strong><br><small>${esc(m.email)}</small></td><td>${m.role==='admin'?'Admin':'Benutzer'}</td><td>${esc(access.groups.find(g=>g.id===m.group_id)?.name||'–')}</td><td>${m.active?(m.user_id?'Aktiv':'Wartet auf ersten Login'):'Deaktiviert'}</td><td>${m.email.toLowerCase()===access.ownerEmail.toLowerCase()||m.id===sessionUser.id?'Geschützt':`<button class="secondary" type="button" data-member="${i}">Bearbeiten</button>`}</td></tr>`).join('')}</tbody></table></div><p>Die Site ist weiterhin privat. Zusätzlich zum Eintrag hier benötigen weitere Personen eine Einladung über die Site-Freigabe.</p></section></div>`;
const group=document.querySelector('#access-group');group.onchange=()=>{document.querySelector('#assignment-topics').innerHTML=access.topics.map(t=>`<label class="choice"><input type="checkbox" name="topicIds" value="${esc(t.id)}" ${access.assignments.some(a=>a.group_id===group.value&&a.topic_id===t.id)?'checked':''}>${esc(t.title)}</label>`).join('')};
const bind=(id,path,method,make)=>{document.querySelector(id).onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{await api(path,method,make(new FormData(form)));toast('Gespeichert.');renderAccess()}catch(error){toast(error.message);button.disabled=false}}};
bind('#group-form','/api/groups','POST',f=>({name:f.get('name')}));bind('#assign-form','/api/assignments','PUT',f=>({groupId:f.get('groupId'),topicIds:f.getAll('topicIds')}));bind('#member-form','/api/members','PUT',f=>({name:f.get('name'),email:f.get('email'),role:f.get('role'),groupId:f.get('groupId'),active:f.has('active')}));
document.querySelectorAll('[data-member]').forEach(button=>button.onclick=()=>{const m=access.members[Number(button.dataset.member)],form=document.querySelector('#member-form');form.elements.name.value=m.name;form.elements.email.value=m.email;form.elements.role.value=m.role;form.elements.groupId.value=m.group_id||'';form.elements.active.checked=!!m.active;form.scrollIntoView({behavior:'smooth'})})
}catch(error){toast(error.message)}}
// Existing browser data remains untouched until the administrator imports it.
if(serverMode&&sessionUser.role==='admin'){
try{const legacy=JSON.parse(localStorage.getItem(KEY));if(legacy&&valid(legacy)&&!localStorage.getItem('lumio-server-migrated')){const banner=document.createElement('section');banner.className='migration-banner glass';banner.innerHTML='<strong>Vorhandene lokale Inhalte gefunden.</strong><p>Du kannst deine bisherigen Oberbegriffe und Tipps in die gemeinsame Datenbank übernehmen. Die lokale Sicherung bleibt erhalten. Bestehende Serverinhalte werden dabei ersetzt.</p><button class="secondary" id="migrate-local">Lokale Inhalte übernehmen</button>';document.querySelector('main').prepend(banner);document.querySelector('#migrate-local').onclick=async()=>{if(!confirm('Die gemeinsamen Lerninhalte durch deine bisherigen lokalen Inhalte ersetzen? Gruppenfreigaben müssen anschliessend neu gesetzt werden.'))return;const old=normalizeState(legacy);old.topics.forEach(t=>delete t.id);state=old;editorIndex=0;lastServerContent='';await scheduleServerSave();if(storageOK){localStorage.setItem('lumio-server-migrated','1');banner.remove();toast('Lokale Inhalte übernommen. Lernfortschritte werden ab jetzt persönlich auf dem Server geführt.')}}}}catch{}}
